19	export const getAttachmentType = (attachment: Attachment) => {
20	  if (isImage(attachment.type)) {
21	    return "image/*";
22	  } else if (attachment.type.startsWith("video")) {
23	    return "video/*";
24	  } else if (attachment.type.startsWith("audio") && !isMidiFile(attachment.type)) {
25	    return "audio/*";
26	  } else if (attachment.type.startsWith("text")) {
27	    return "text/*";
28	  } else if (attachment.type.startsWith("application/epub+zip")) {
